arguments.command:
curl -s -H "Authorization: Bearer <TOKEN>" "https://api.box.com/2.0/folders/8100/items?limit=200" | python3 -c "
import json,sys
d=json.load(sys.stdin)
for e in d.get('entries',[]):
    if e['type']=='folder':
        o=e.get('owned_by') or {}
        c=e.get('created_by') or {}
        print(e['id'],'|',e['name'],'| owned_by:',o.get('name'),'| created_by:',c.get('name'))
print('---')
print('total:', d.get('total_count'))
"

